document.addEventListener('DOMContentLoaded', function() {
  const exitModal = document.getElementById('exitModal');
  const confirmExitBtn = document.getElementById('confirmExitBtn');
  const cancelExitBtn = document.getElementById('cancelExitBtn');
  let targetUrl = ''; // To store the URL of the external link

  // List of specific external sites to trigger the modal for
  const specificExternalSites = [
    'unipaygold.unibank.com',
    'cityofpeabodyma.municipalonlinepayments.com',
	  'main.govpilot.com',
	  'peabodyma.mapgeo.io',
	  'peabodyma.portal.opengov.com',
	  'www.surveymonkey.com'
  ];

  document.body.addEventListener('click', function(event) {
    let link = event.target.closest('a'); // Find the closest ancestor that is an <a> tag

    if (link && link.href) {
      const currentDomain = window.location.hostname;
      const targetDomain = new URL(link.href).hostname;

      // Check if it's an external link AND if its domain is in our specific list
      if (targetDomain !== currentDomain && specificExternalSites.includes(targetDomain)) {
        event.preventDefault(); // Prevent default navigation
        targetUrl = link.href; // Store the target URL
        exitModal.style.display = 'block'; // Show the modal
      }
    }
  });

  confirmExitBtn.addEventListener('click', function() {
    exitModal.style.display = 'none'; // Hide the modal
    window.open(targetUrl, '_blank'); // Navigate to the external site
  });

  cancelExitBtn.addEventListener('click', function() {
    exitModal.style.display = 'none'; // Hide the modal
    targetUrl = ''; // Clear the stored URL
  });
});
 

     
